import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.CDU0sSpB.js";const d="/hearth-os/assets/hearth-brand-board.owAef18o.svg",p=JSON.parse('{"title":"Hearth Brand Mark","description":"","frontmatter":{},"headers":[],"relativePath":"brand/README.md","filePath":"brand/README.md","lastUpdated":1793797632000}'),n={name:"brand/README.md"};function s(h,t,i,l,c,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="hearth-brand-mark" tabindex="-1">Hearth Brand Mark <a class="header-anchor" href="#hearth-brand-mark" aria-label="Permalink to &quot;Hearth Brand Mark&quot;">​</a></h1><p><img src="'+d+'" alt="Hearth brand board"></p><h2 id="direction" tabindex="-1">Direction <a class="header-anchor" href="#direction" aria-label="Permalink to &quot;Direction&quot;">​</a></h2><p><strong>The Hearth Arch</strong> is an open stone arch holding a warm ember.</p><ul><li>The arch is the trust boundary around the personal Agent OS.</li><li>The ember is the durable work and the agent core that stays alive between runs.</li><li>The opening is the human path back in: approval, takeover, and recovery.</li><li>The continuous rounded stroke reads as an operating loop, while its open base avoids the feeling of a sealed black box.</li></ul><p>The mark avoids the usual AI vocabulary of brains, sparkles, robots, and neural networks. It is intended to feel warm, private, self-hosted, and dependable rather than futuristic for its own sake.</p><h2 id="assets" tabindex="-1">Assets <a class="header-anchor" href="#assets" aria-label="Permalink to &quot;Assets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Use</th></tr></thead><tbody><tr><td><code>hearth-mark.svg</code></td><td>Primary symbol on light backgrounds</td></tr><tr><td><code>hearth-mark-reverse.svg</code></td><td>Symbol on charcoal backgrounds</td></tr><tr><td><code>hearth-app-icon.svg</code></td><td>App icon and avatar source</td></tr><tr><td><code>hearth-logo.svg</code></td><td>Organization lockup</td></tr><tr><td><code>hearth-os-logo.svg</code></td><td>Hearth OS product lockup</td></tr><tr><td><code>hearth-brand-board.svg</code></td><td>Concept overview and usage reference</td></tr></tbody></table><p>PNG exports are included for quick preview and for environments that do not support SVG.</p><h2 id="palette" tabindex="-1">Palette <a class="header-anchor" href="#palette" aria-label="Permalink to &quot;Palette&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Hex</th><th>Role</th></tr></thead><tbody><tr><td>Charcoal</td><td><code>#1B1815</code></td><td>Primary ink and dark surface</td></tr><tr><td>Ember</td><td><code>#F26B38</code></td><td>Agent core and active state</td></tr><tr><td>Sand</td><td><code>#F1E8DA</code></td><td>Warm background</td></tr><tr><td>Cream</td><td><code>#FFF9F2</code></td><td>Reverse mark and light surface</td></tr><tr><td>Stone</td><td><code>#8C8378</code></td><td>Secondary text and rules</td></tr></tbody></table><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><ul><li>Keep clear space around the mark equal to at least half the width of the ember.</li><li>Use the arch-only symbol without a wordmark below 40 px.</li><li>Do not add glows, gradients, shadows, or photo textures to the mark.</li><li>Do not stretch, skew, or rotate the mark.</li><li>Keep the ember orange as the only accent color in the primary identity.</li><li>The <code>HEARTH</code> wordmark is a working organization name until the organization has a final name; replace the text without changing the symbol.</li></ul>',13)])])}const m=e(n,[["render",s]]);export{p as __pageData,m as default};
